=== backend/src/main/java/com/example/dealership/error/GlobalExceptionHandler.java
     1	package com.example.dealership.error;
     2	
     3	import java.util.Arrays;
     4	import java.util.Comparator;
     5	import java.util.List;
     6	import java.util.stream.Collectors;
     7	
     8	import com.fasterxml.jackson.databind.JsonMappingException;
     9	import com.fasterxml.jackson.databind.exc.InvalidFormatException;
    10	
    11	import org.springframework.core.Ordered;
    12	import org.springframework.core.annotation.Order;
    13	import org.springframework.dao.DataIntegrityViolationException;
    14	import org.springframework.http.HttpStatus;
    15	import org.springframework.http.ProblemDetail;
    16	import org.springframework.http.converter.HttpMessageNotReadableException;
    17	import org.springframework.validation.FieldError;
    18	import org.springframework.validation.ObjectError;
    19	import org.springframework.web.bind.MethodArgumentNotValidException;
    20	import org.springframework.web.bind.annotation.ExceptionHandler;
    21	import org.springframework.web.bind.annotation.RestControllerAdvice;
    22	
    23	@RestControllerAdvice
    24	@Order(Ordered.HIGHEST_PRECEDENCE)
    25	public class GlobalExceptionHandler {
    26	
    27	    @ExceptionHandler(MethodArgumentNotValidException.class)
    28	    public ProblemDetail handleMethodArgumentNotValid(MethodArgumentNotValidException ex) {
    29	        List<ValidationError> errors = ex.getBindingResult().getAllErrors().stream()
    30	                .map(GlobalExceptionHandler::toValidationError)
    31	                .sorted(Comparator.comparing(ValidationError::field, Comparator.nullsFirst(Comparator.naturalOrder()))
    32	                        .thenComparing(ValidationError::message))
    33	                .toList();
    34	        return validationProblem(errors);
    35	    }
    36	
    37	    @ExceptionHandler(HttpMessageNotReadableException.class)
    38	    public ProblemDetail handleNotReadable(HttpMessageNotReadableException ex) {
    39	        return validationProblem(List.of(toValidationError(ex.getCause())));
    40	    }
    41	
    42	    @ExceptionHandler(NotFoundException.class)
    43	    public ProblemDetail handleNotFound(NotFoundException ex) {
    44	        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
    45	    }
    46	
    47	    @ExceptionHandler(ConflictException.class)
    48	    public ProblemDetail handleConflict(ConflictException ex) {
    49	        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, ex.getMessage());
    50	    }
    51	
    52	    // Safety net for races only: uniqueness rules are checked by the services.
    53	    @ExceptionHandler(DataIntegrityViolationException.class)
    54	    public ProblemDetail handleDataIntegrityViolation(DataIntegrityViolationException ex) {
    55	        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, "Request conflicts with existing data");
    56	    }
    57	
    58	    private static ProblemDetail validationProblem(List<ValidationError> errors) {
    59	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Validation failed");
    60	        problem.setProperty("errors", errors);
    61	        return problem;
    62	    }
    63	
    64	    private static ValidationError toValidationError(ObjectError error) {
    65	        String field = error instanceof FieldError fieldError ? fieldError.getField() : null;
    66	        return new ValidationError(field, error.getDefaultMessage());
    67	    }
    68	
    69	    private static ValidationError toValidationError(Throwable cause) {
    70	        if (!(cause instanceof JsonMappingException mapping) || mapping.getPath().isEmpty()) {
    71	            return new ValidationError(null, "request body must be valid JSON");
    72	        }
    73	        String field = mapping.getPath().stream()
    74	                .map(reference -> reference.getFieldName() != null
    75	                        ? "." + reference.getFieldName()
    76	                        : "[" + reference.getIndex() + "]")
    77	                .collect(Collectors.joining())
    78	                .replaceFirst("^\\.", "");
    79	        if (cause instanceof InvalidFormatException invalidFormat && invalidFormat.getTargetType().isEnum()) {
    80	            String allowed = Arrays.stream(invalidFormat.getTargetType().getEnumConstants())
    81	                    .map(String::valueOf)
    82	                    .collect(Collectors.joining(", "));
    83	            return new ValidationError(field, "must be one of: " + allowed);
    84	        }
    85	        return new ValidationError(field, "has an invalid value");
    86	    }
    87	}
