     1	package com.example.dealership.vehicle;
     2	
     3	import java.time.Year;
     4	
     5	import jakarta.validation.ConstraintValidator;
     6	import jakarta.validation.ConstraintValidatorContext;
     7	
     8	public class ProductionYearValidator implements ConstraintValidator<ProductionYear, Integer> {
     9	
    10	    static final int MIN_YEAR = 1990;
    11	
    12	    @Override
    13	    public boolean isValid(Integer value, ConstraintValidatorContext context) {
    14	        if (value == null) {
    15	            return true;
    16	        }
    17	        return value >= MIN_YEAR && value <= Year.now().getValue() + 1;
    18	    }
    19	}
