=== backend/src/main/java/com/example/dealership/vehicle/VehicleService.java
     1	package com.example.dealership.vehicle;
     2	
     3	import java.util.List;
     4	
     5	import com.example.dealership.error.ConflictException;
     6	import com.example.dealership.error.NotFoundException;
     7	
     8	import org.springframework.data.domain.Sort;
     9	import org.springframework.stereotype.Service;
    10	import org.springframework.transaction.annotation.Transactional;
    11	
    12	@Service
    13	@Transactional(readOnly = true)
    14	public class VehicleService {
    15	
    16	    private final VehicleRepository vehicleRepository;
    17	
    18	    public VehicleService(VehicleRepository vehicleRepository) {
    19	        this.vehicleRepository = vehicleRepository;
    20	    }
    21	
    22	    public List<VehicleResponse> findAll() {
    23	        return vehicleRepository.findAll(Sort.by("id")).stream()
    24	                .map(VehicleMapper::toResponse)
    25	                .toList();
    26	    }
    27	
    28	    public VehicleResponse findById(Long id) {
    29	        return VehicleMapper.toResponse(getVehicle(id));
    30	    }
    31	
    32	    @Transactional
    33	    public VehicleResponse create(VehicleRequest request) {
    34	        if (vehicleRepository.existsByVin(request.vin())) {
    35	            throw vinAlreadyExists(request.vin());
    36	        }
    37	        Vehicle vehicle = vehicleRepository.save(VehicleMapper.toEntity(request));
    38	        return VehicleMapper.toResponse(vehicle);
    39	    }
    40	
    41	    @Transactional
    42	    public VehicleResponse update(Long id, VehicleRequest request) {
    43	        Vehicle vehicle = getVehicle(id);
    44	        if (vehicleRepository.existsByVinAndIdNot(request.vin(), id)) {
    45	            throw vinAlreadyExists(request.vin());
    46	        }
    47	        VehicleMapper.updateEntity(vehicle, request);
    48	        return VehicleMapper.toResponse(vehicleRepository.save(vehicle));
    49	    }
    50	
    51	    @Transactional
    52	    public void delete(Long id) {
    53	        vehicleRepository.delete(getVehicle(id));
    54	    }
    55	
    56	    private Vehicle getVehicle(Long id) {
    57	        return vehicleRepository.findById(id)
    58	                .orElseThrow(() -> new NotFoundException("Vehicle with id " + id + " not found"));
    59	    }
    60	
    61	    private static ConflictException vinAlreadyExists(String vin) {
    62	        return new ConflictException("Vehicle with VIN " + vin + " already exists");
    63	    }
    64	}
