     1	#!/usr/bin/env bash
     2	# Runs all backend and frontend tests. Exits with a non-zero code if anything fails.
     3	# Both parts always run; a summary of both is printed at the end.
     4	set -uo pipefail
     5	cd "$(dirname "$0")"
     6	
     7	source ./check-node.sh
     8	
     9	backend_status=0
    10	(cd backend && ./mvnw test) || backend_status=$?
    11	
    12	frontend_status=0
    13	(
    14	  set -e
    15	  cd frontend
