50	    16	export function problemDetailMessage(error: unknown): string {
51	    17	  if (error instanceof HttpErrorResponse) {
52	    18	    const problem = error.error as ProblemDetail | null;
53	    19	    return problem?.detail ?? problem?.title ?? error.message;
54	    20	  }
55	    21	  return 'Unexpected error';
56	    22	}
