58	    24	export function loadErrorMessage(error: unknown, notFoundMessage: string): string {
59	    25	  if (error instanceof HttpErrorResponse && error.status === 404) {
60	    26	    return notFoundMessage;
61	    27	  }
62	    28	  return problemDetailMessage(error);
63	    29	}
64	    30	
65	    31	export function problemDetailToFormErrors<T extends object>(
66	    32	  error: unknown,
67	    33	  form: FieldTree<T>,
68	    34	): ValidationError.WithOptionalFieldTree[] {
69	    35	  const fieldErrors =
70	    36	    error instanceof HttpErrorResponse ? (error.error as ProblemDetail | null)?.errors : undefined;
71	    37	  if (!fieldErrors?.length) {
72	    38	    // A 409 conflict carries no field errors: it is an error of the whole form, not of a field.
73	    39	    return [{ kind: 'server', message: problemDetailMessage(error), fieldTree: form }];
74	    40	  }
75	    41	  const fields = form as unknown as Record<string, FieldTree<unknown> | undefined>;
76	    42	  return fieldErrors.map(({ field, message }) => ({
77	    43	    kind: 'server',
78	    44	    message,
79	    45	    fieldTree: (field === null ? undefined : fields[field]) ?? form,
80	    46	  }));
